class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        tails = [] # 递增的, tails[i]表示长度为i+1的递增子序列的最小末尾值
        for num in nums:
            left, right = 0, len(tails)
            while left < right:
                mid = (left + right) // 2
                if tails[mid] < num: # 二分目的: 在tails中找到第一个>=num的值
                    left = mid + 1
                else:
                    right = mid

            if left == len(tails):
                tails.append(num)
            else:
                tails[left] = num
        return len(tails)
